cd "/c/visual projects/alpha"; ssh calc 'cd /data/tk0393/tk409/Rq && python3 - <<EOF
import csv,glob,collections,statistics as st
P={"AGENCY","ALLINU","CLAUDIA","EMBER","FONE","GT","HOOKED","KIMCHI","LAPTOP","PAID","SI","STAMP","SUE","Q"}
rows=[]
for f in glob.glob("Rq-*-eps.csv"):
    for r in csv.DictReader(open(f)):
        if r["coin"] in P and r["h"]=="60" and float(r["X"])==0.10 and float(r["W"])==1800: rows.append(r)
g=[float(r["gross_bp"]) for r in rows]
c=[float(r["ctrl_bp"]) for r in rows if r["ctrl_bp"] not in ("","nan","NaN")]
print(len(rows), round(sum(g)/len(g),2), round(sum(c)/len(c),2), len(c))
print(collections.Counter(r["coin"] for r in rows))
d=collections.defaultdict(list)
for r in rows: d[r["day"]].append(float(r["gross_bp"]))
print({k:(len(v),round(sum(v)/len(v),1)) for k,v in sorted(d.items())})
q=[float(r["gross_bp"]) for r in rows if r["coin"]=="Q"]; print("Q", len(q), round(sum(q)/len(q),1), "max", max(g), "min", min(g), "med", st.median(g))
EOF' 2>&1 | tail -6

